import re

def check_rmnet_ipv6():
    out = adb_shell("ip -6 addr show 2>/dev/null")
    iface = ""
    for line in out.splitlines():
        m = re.match(r"\s*\d+:\s*(rmnet_data\d+)[@:]", line)
        if m:
            iface = m.group(1)
            continue
        if iface and "inet6" in line and "scope global" in line:
            addr = line.strip().split()[1]
            return True, f"{iface} IPv6={addr}"
    return False, "rmnet_data 글로벌 IPv6 없음"

return check_rmnet_ipv6()
